c1 = bytes.fromhex("")
c2 = bytes.fromhex("")
c3 = bytes.fromhex("")

def xor(a, b):
    return bytes([x ^ y for x, y in zip(a, b)])

p2_unit = b"hello bro, Im hacker"
p2 = (p2_unit * 12)[:227]
k = xor(c2, p2)
p1 = xor(c1, k)
p3 = xor(c3, k)
print("p1:", p1)
print("p2:", p2[:44])
print("p3:", p3[:44])
print("p3 full:", p3)


